package org.sleepwell.app;
import java.util.*;import java.util.regex.*;
/** Deliberately narrow English relative durations; speech output never selects or saves an alarm. */
final class RelativeTimeSpeech {
 static final class Candidate {final int minutes;final String heard,confidence;Candidate(int minutes,String heard,String confidence){this.minutes=minutes;this.heard=heard;this.confidence=confidence;}}
 private static final Pattern HOURS=Pattern.compile("(?:in )?([a-z0-9 -]+) (?:hour|hours|hr|hrs)(?: (?:and )?([a-z0-9 -]+) (?:minute|minutes|min|mins))?");
 private static final Pattern MINUTES=Pattern.compile("(?:in )?([a-z0-9 -]+) (?:minute|minutes|min|mins)");
 static int parse(String raw){if(raw==null||raw.length()>120)throw new IllegalArgumentException("Say a short relative duration.");String text=raw.toLowerCase(Locale.ROOT).strip().replaceAll("\\s+"," ");if(text.endsWith("."))text=text.substring(0,text.length()-1);Matcher hours=HOURS.matcher(text),minutes=MINUTES.matcher(text);int total;if(hours.matches()){int h=number(hours.group(1)),m=hours.group(2)==null?0:number(hours.group(2));if(h<0||h>24||m<0||m>59)throw new IllegalArgumentException("Invalid hours or minutes.");total=h*60+m;}else if(minutes.matches())total=number(minutes.group(1));else throw new IllegalArgumentException("Use a phrase such as 'in 2 hours 15 minutes'. Clock times and fractions are not supported.");if(total<1||total>1440)throw new IllegalArgumentException("Choose 1 minute to 24 hours.");return total;}
 private static int number(String raw){String text=raw.strip().replace('-',' ');if(text.matches("[0-9]{1,4}"))return Integer.parseInt(text);if(text.equals("a")||text.equals("an"))return 1;String[] small={"zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"};for(int n=0;n<small.length;n++)if(text.equals(small[n]))return n;String[] tens={"twenty","thirty","forty","fifty"};for(int n=0;n<tens.length;n++){if(text.equals(tens[n]))return 20+n*10;for(int one=1;one<=9;one++)if(text.equals(tens[n]+" "+small[one]))return 20+n*10+one;}throw new IllegalArgumentException("That number is not supported. Type the duration instead.");}
 static List<Candidate> candidates(List<String> results,float[] scores){if(results==null||results.isEmpty())throw new IllegalArgumentException("No speech text was returned. Try again or type a duration.");List<Candidate> choices=new ArrayList<>();Set<Integer> seen=new HashSet<>();for(int n=0;n<Math.min(3,results.size());n++){String heard=results.get(n);try{int minutes=parse(heard);if(!seen.add(minutes))continue;float score=scores!=null&&scores.length==results.size()?scores[n]:-1;String confidence=!Float.isFinite(score)||score<0||score>1?"confidence unavailable":score<.6f?"low recognition confidence":String.format(Locale.ROOT,"recognition confidence %.0f%%",score*100);choices.add(new Candidate(minutes,heard,confidence));}catch(IllegalArgumentException unsupported){}}if(choices.isEmpty())throw new IllegalArgumentException("No supported duration was recognized. Say 'in 2 hours 15 minutes', or type a duration.");return choices;}
 private RelativeTimeSpeech(){}
}
